"""
KNOWLEDGE BASE INITIALIZATION
Role: Core entry point for the system's foundational knowledge base.
Integration: Manages domain-specific knowledge registries and schema validation.
Dependencies: registry_utils.py (Registry management), telemetry_utils.py (Telemetry)

This module serves as the primary interface for accessing and validating 
system-wide knowledge, ensuring that all data injected into the diagnostic 
engine adheres to strict structural integrity requirements.
"""

from __future__ import annotations

import copy
import logging
import threading
import time
from typing import Any, Callable, Dict, Final, List, NamedTuple, Optional, TypedDict

# Configure logging for the knowledge base module prior to import fallbacks
logger: logging.Logger = logging.getLogger(__name__)

# Resilient fallback mock registry if unavailable during isolated bootstrap
class _FallbackRegistry:
    """Thread-safe resilient fallback registry for standalone and bootstrap contexts."""

    def __init__(self) -> None:
        self._lock: threading.RLock = threading.RLock()
        self._store: Dict[str, Any] = {}
        self._validators: Dict[str, Callable[[Any], bool]] = {}

    def register(self, key: str, value: Any, validator: Optional[Callable[[Any], bool]] = None) -> None:
        if not isinstance(key, str) or not key.strip():
            raise ValueError(f"Invalid registry key: {key!r}")
        with self._lock:
            self._store[key] = value
            if validator is not None:
                self._validators[key] = validator
            elif key in self._validators:
                del self._validators[key]

    def get(self, key: str) -> Any:
        with self._lock:
            if key not in self._store:
                raise KeyError(key)
            return self._store[key]

    def list_keys(self) -> List[str]:
        with self._lock:
            return list(self._store.keys())

    def validate(self, key: str) -> bool:
        with self._lock:
            if key not in self._store:
                return False
            validator = self._validators.get(key)
            if validator is None:
                return True
            try:
                return bool(validator(self._store[key]))
            except Exception as eval_err:
                logger.warning(
                    "FallbackRegistry validation raised exception for key '%s': %s",
                    key,
                    eval_err,
                    exc_info=True,
                )
                return False

try:
    from .registry_utils import registry
except ImportError:
    try:
        from registry_utils import registry  # type: ignore
    except ImportError:
        registry = _FallbackRegistry()  # type: ignore

try:
    from .telemetry_utils import get_system_telemetry
except ImportError:
    try:
        from telemetry_utils import get_system_telemetry  # type: ignore
    except ImportError:
        def get_system_telemetry() -> Dict[str, Any]:
            return {
                "timestamp": time.time(),
                "status": "FALLBACK_TELEMETRY",
                "initialized": False,
            }

# Immutable set of operational modes for O(1) validation lookup
_VALID_OPERATIONAL_MODES: Final[frozenset[str]] = frozenset(
    {"DEVELOPMENT", "STAGING", "PRODUCTION"}
)

# Concurrency guard for idempotent mutations
_INIT_LOCK: Final[threading.RLock] = threading.RLock()


class ValidationResult(NamedTuple):
    """Encapsulates item-level validation outcome and error telemetry."""

    is_valid: bool
    errors: List[str]
    timestamp: float


class SchemaDiagnosticReport(NamedTuple):
    """Structured diagnostic snapshot for registry schema integrity."""

    total_keys: int
    passed_keys: int
    failed_keys: List[str]
    validation_results: Dict[str, ValidationResult]
    duration_ms: float
    timestamp: float


class InitializationReport(TypedDict):
    """Typed dictionary schema representing the initialization report payload."""

    status: str
    timestamp: float
    duration_ms: float
    telemetry: Dict[str, Any]


class KnowledgeBaseError(Exception):
    """Base exception class for Knowledge Base domain operations."""

    pass


class KnowledgeBaseInitError(KnowledgeBaseError, RuntimeError):
    """Raised when knowledge base initialization encounters an unrecoverable error."""

    pass


def _validate_system_version(value: Any) -> bool:
    """Fast validation predicate for system version integrity."""
    return isinstance(value, str) and len(value) >= 8 and value.endswith("-STABLE")


def _validate_operational_mode(value: Any) -> bool:
    """Fast set-based validation predicate for operational modes."""
    return isinstance(value, str) and value in _VALID_OPERATIONAL_MODES


def initialize_knowledge_base() -> InitializationReport:
    """Initializes the knowledge base registry with core domain schemas.

    Implements diagnostic-aware startup procedures and telemetry logging.

    Returns:
        InitializationReport: Structured report containing status, timing metrics, and system telemetry.

    Raises:
        KnowledgeBaseInitError: If critical failure occurs during schema registration or telemetry collection.
    """
    with _INIT_LOCK:
        start_time: float = time.perf_counter()
        init_timestamp: float = time.time()

        try:
            # Register system version schema validator
            registry.register(
                "system_version",
                "1.0.0-STABLE",
                _validate_system_version,
            )

            # Register operational mode schema validator
            registry.register(
                "operational_mode",
                "PRODUCTION",
                _validate_operational_mode,
            )

            telemetry: Dict[str, Any]
            try:
                raw_telemetry: Any = get_system_telemetry()
                if isinstance(raw_telemetry, dict):
                    telemetry = dict(raw_telemetry)
                else:
                    telemetry = {"raw_telemetry": raw_telemetry, "timestamp": init_timestamp}
            except Exception as tel_err:
                logger.warning(
                    "Telemetry collection encountered a non-fatal anomaly: %s",
                    tel_err,
                    exc_info=True,
                )
                telemetry = {
                    "status": "TELEMETRY_DEGRADED",
                    "error": str(tel_err),
                    "timestamp": init_timestamp,
                }

            duration_ms: float = (time.perf_counter() - start_time) * 1000.0

            logger.info(
                "Knowledge base initialized in %.2fms. Telemetry: %s",
                duration_ms,
                telemetry,
            )

            return {
                "status": "INITIALIZED",
                "timestamp": init_timestamp,
                "duration_ms": duration_ms,
                "telemetry": telemetry,
            }
        except Exception as e:
            logger.critical(
                "Critical failure during knowledge base initialization: %s",
                e,
                exc_info=True,
            )
            raise KnowledgeBaseInitError(
                f"Knowledge Base Initialization Failed: {e}"
            ) from e


def get_knowledge(key: str) -> Optional[Any]:
    """Retrieves a specific piece of knowledge from the registry.

    Args:
        key: The unique string identifier for the knowledge item.

    Returns:
        The registered value associated with the key, or None if retrieval fails or key is missing.
    """
    if not isinstance(key, str) or not key.strip():
        logger.warning("Invalid key type or empty key string provided: %r", key)
        return None

    try:
        val: Any = registry.get(key)
        return val
    except KeyError:
        logger.debug("Key '%s' not found in registry.", key)
        return None
    except Exception as e:
        logger.warning("Failed to retrieve key '%s': %s", key, e, exc_info=True)
        return None


def get_diagnostic_report() -> SchemaDiagnosticReport:
    """Generates an in-depth diagnostic integrity report across all registered schemas.

    Returns:
        SchemaDiagnosticReport: Detailed breakdown of registry validation state.
    """
    start_time: float = time.perf_counter()
    report_ts: float = time.time()
    results: Dict[str, ValidationResult] = {}
