"""
TELEMETRY TYPES DEFINITION
Role: Defines the foundational telemetry structures for the encyclopedia engineering system.
Integration: Used by registry_telemetry.py and telemetry_stats_engine.py to ensure 
             consistent data shapes across the diagnostic pipeline.
Architectural Note: Aligned with AI_Agent_OS enterprise diagnostic observability 
standards with defensive validation and atomic fallbacks.
"""

from __future__ import annotations

import copy
import math
import sys
import threading
import time
import uuid
from typing import (
    Any,
    Dict,
    Final,
    List,
    Mapping,
    Optional,
    TypedDict,
    Union,
    final,
)

if sys.version_info >= (3, 10):
    from typing import TypeGuard
else:
    from typing_extensions import TypeGuard

try:
    from .diagnostic_logger_ext import DiagnosticLogger
except ImportError:
    try:
        from diagnostic_logger_ext import DiagnosticLogger  # type: ignore
    except ImportError:
        class DiagnosticLogger:  # type: ignore
            """Fallback diagnostic logger when diagnostic_logger_ext is unavailable."""
            def log_event(self, event_name: str, payload: Dict[str, Any]) -> None:
                pass


__all__ = [
    "TelemetryHealthStatus",
    "TelemetryDiagnosticMetadata",
    "TelemetrySnapshot",
    "TelemetryEvent",
    "create_default_health_status",
    "create_default_diagnostic_metadata",
    "create_telemetry_snapshot",
    "create_telemetry_event",
    "is_telemetry_health_status",
    "is_telemetry_diagnostic_metadata",
    "is_telemetry_snapshot",
    "is_telemetry_event",
    "DEFAULT_NODE_VERSION",
    "DEFAULT_SNAPSHOT_VERSION",
    "DEFAULT_HEALTH_STATUS_CODE",
    "DiagnosticLogger",
]

DEFAULT_NODE_VERSION: Final[str] = "v1.0.0"
DEFAULT_SNAPSHOT_VERSION: Final[str] = "1.0.0"
DEFAULT_HEALTH_STATUS_CODE: Final[str] = "OK"


@final
class TelemetryHealthStatus(TypedDict, total=True):
    """Represents the health state of a telemetry-enabled component."""
    is_healthy: bool
    error_count: int
    last_check_timestamp: float
    status_code: str


@final
class TelemetryDiagnosticMetadata(TypedDict, total=True):
    """Standardized metadata for telemetry snapshots."""
    node_version: str
    platform: str
    uptime_seconds: float
    memory_usage_bytes: int
    thread_id: int


@final
class TelemetrySnapshot(TypedDict, total=True):
    """
    Comprehensive telemetry snapshot structure.
    Aligned with AI_Agent_OS diagnostic standards.
    """
    access_count: int
    uptime_seconds: float
    version: str
    metadata: TelemetryDiagnosticMetadata
    health: TelemetryHealthStatus
    tags: List[str]
    custom_metrics: Dict[str, Any]


@final
class TelemetryEvent(TypedDict, total=True):
    """Represents a specific telemetry event occurrence."""
    event_id: str
    event_type: str
    payload: Dict[str, Any]
    timestamp: float


def _safe_dict_copy(data: Any) -> Dict[str, Any]:
    """Defensively deep-copies arbitrary dictionary or mapping structures with atomic fallbacks."""
    if not isinstance(data, (dict, Mapping)):
        return {}
    try:
        return copy.deepcopy(dict(data))
    except Exception:
        fallback: Dict[str, Any] = {}
        try:
            for k, v in data.items():
                try:
                    fallback[str(k)] = copy.copy(v)
                except Exception:
                    fallback[str(k)] = str(v)
            return fallback
        except Exception:
            return {}


def _safe_float(value: Any, default: float = 0.0) -> float:
    """Converts a value to a finite float or returns the provided default."""
    try:
        res = float(value)
        if math.isnan(res) or math.isinf(res):
            return default
        return res
    except (ValueError, TypeError):
        return default


# Helper Factory Functions for Safe & Validated Instantiation

def create_default_health_status(
    is_healthy: bool = True,
    error_count: int = 0,
    status_code: str = DEFAULT_HEALTH_STATUS_CODE,
    timestamp: Optional[float] = None,
) -> TelemetryHealthStatus:
    """Creates a validated TelemetryHealthStatus instance with modern default values."""
    try:
        if isinstance(error_count, bool):
            err_count_int = 1 if error_count else 0
        else:
            err_count_int = max(0, int(error_count))
    except (ValueError, TypeError, OverflowError):
        err_count_int = 0

    if timestamp is None:
        ts_val = time.time()
    else:
        ts_val = _safe_float(timestamp, default=time.time())
        if ts_val < 0.0:
            ts_val = time.time()

    return TelemetryHealthStatus(
        is_healthy=bool(is_healthy),
        error_count=err_count_int,
        last_check_timestamp=ts_val,
        status_code=str(status_code) if status_code is not None else DEFAULT_HEALTH_STATUS_CODE,
    )


def create_default_diagnostic_metadata(
    node_version: str = DEFAULT_NODE_VERSION,
    platform: str = sys.platform,
    uptime_seconds: float = 0.0,
    memory_usage_bytes: int = 0,
    thread_id: int = 0,
) -> TelemetryDiagnosticMetadata:
    """Creates a validated TelemetryDiagnosticMetadata instance with runtime telemetry metadata defaults."""
    uptime_val = max(0.0, _safe_float(uptime_seconds, default=0.0))

    try:
        if isinstance(memory_usage_bytes, bool):
            mem_val = 0
        else:
            mem_val = max(0, int(memory_usage_bytes))
    except (ValueError, TypeError, OverflowError):
        mem_val = 0

    try:
        if isinstance(thread_id, bool):
            tid_val = threading.get_ident()
        else:
            tid_val = int(thread_id)
            if tid_val == 0:
                tid_val = threading.get_ident()
    except (ValueError, TypeError, OverflowError):
        tid_val = threading.get_ident()

    return TelemetryDiagnosticMetadata(
        node_version=str(node_version) if node_version is not None else DEFAULT_NODE_VERSION,
        platform=str(platform) if platform is not None else sys.platform,
        uptime_seconds=uptime_val,
        memory_usage_bytes=mem_val,
        thread_id=tid_val,
    )


def create_telemetry_snapshot(
    version: str = DEFAULT_SNAPSHOT_VERSION,
    access_count: int = 0,
    uptime_seconds: float = 0.0,
    health: Optional[TelemetryHealthStatus] = None,
    metadata: Optional[TelemetryDiagnosticMetadata] = None,
    tags: Optional[List[str]] = None,
    custom_metrics: Optional[Dict[str, Any]] = None,
) -> TelemetrySnapshot:
    """Factory builder for constructing a complete TelemetrySnapshot struct safely."""
    try:
        if isinstance(access_count, bool):
            access_val = 1 if access_count else 0
        else:
            access_val = max(0, int(access_count))
    except (ValueError, TypeError, OverflowError):
        access_val = 0

    uptime_val = max(0.0, _safe_float(uptime_seconds, default=0.0))

    if tags is not None:
        if isinstance(tags, (str, bytes)):
            safe_tags = [str(tags)]
        else:
            try:
                safe_tags = [str(t) for t in tags]
            except Exception:
                safe_tags = []
    else:
        safe_tags = []

    safe_metrics = _safe_dict_copy(custom_metrics)

    if metadata is not None and is_telemetry_diagnostic_metadata(metadata):
        safe_metadata = TelemetryDiagnosticMetadata(
            node_version=str(metadata["node_version"]),
            platform=str(metadata["platform"]),
            uptime_seconds=max(0.0, float(metadata["uptime_seconds"])),
            memory_usage_bytes=max(0, int(metadata["memory_usage_bytes"])),
            thread_id=int(metadata["thread_id"]),
        )
    else:
        safe_metadata = create_default_diagnostic_metadata(uptime_seconds=uptime_val)

    if health is not None and is_telemetry_health_status(health):
        safe_health = TelemetryHealthStatus(
            is_healthy=bool(health["is_healthy"]),
            error_count=max(0, int(health["error_count"])),
            last_check_timestamp=float(health["last_check_timestamp"]),
            status_code=str(health["status_code"]),
        )
    else:
        safe_health = create_default_health_status()

    return TelemetrySnapshot(
        access_count=access_val,
        uptime_seconds=uptime_val,
        version=str(version) if version is not None else DEFAULT_SNAPSHOT_VERSION,
        metadata=safe_metadata,
        health=safe_health,
        tags=safe_tags,
        custom_metrics=safe_metrics,
    )


def create_telemetry_event(
    event_type: str,
    payload: Optional[Dict[str, Any]] = None,
    event_id: Optional[str] = None,
    timestamp: Optional[float] = None,
) -> TelemetryEvent:
    """Factory builder for creating a validated TelemetryEvent struct safely."""
    if timestamp is None:
        ts_val = time.time()
    else:
        ts_val = _safe_float(timestamp, default=time.time())
        if ts_val < 0.0:
            ts_val = time.time()

    safe_event_id = str(event_id) if event_id is not None else str(uuid.uuid4())
    safe_event_type = str(event_type) if event_type is not None else "unknown_event"
    safe_payload = _safe_dict_copy(payload)

    return TelemetryEvent(
        event_id=safe_event_id,
        event_type=safe_event_type,
        payload=safe_payload,
        timestamp=ts_val,
    )


# Runtime Type Guard Validation Utilities

def is_telemetry_health_status(obj: Any) -> TypeGuard[TelemetryHealthStatus]:
    """TypeGuard for validating TelemetryHealthStatus runtime dict contracts."""
    if not isinstance(obj, dict):
        return False

    if not all(k in obj for k in ("is_healthy", "error_count", "last_check_timestamp", "status_code")):
        return False

    err_cnt = obj["error_count"]
    last_chk = obj["last_check_timestamp"]

    return (
        isinstance(obj["is_healthy"], bool)
        and isinstance(err_cnt, int)
        and not isinstance(err_cnt, bool)
        and err_cnt >= 0
        and isinstance(last_chk, (int, float))
        and not isinstance(last_chk, bool)
        and math.isfinite(float(last_chk))
        and float(last_chk) >= 0.0
        and isinstance(obj["status_code"], str)
    )


def is_telemetry_diagnostic_metadata(obj: Any) -> TypeGuard[TelemetryDiagnosticMetadata]:
    """TypeGuard for validating TelemetryDiagnosticMetadata runtime dict contracts."""
    if not isinstance(obj, dict):
        return False

    if not all(k in obj for k in ("node_version", "platform", "uptime_seconds", "memory_usage_bytes", "thread_id")):
        return False

    uptime = obj["uptime_seconds"]
    mem_usage = obj["memory_usage_bytes"]
    tid = obj["thread_id"]

