def generate_telemetry_metadata(
    extra_context: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Generates standard telemetry metadata for diagnostic results.

    Args:
        extra_context: Optional mapping to merge into telemetry metadata.

    Returns:
        Dict[str, Any]: Telemetry dictionary containing timestamp, thread_id, and version.
    """
    now = time.time()
    try:
        thread_id: int = threading.get_ident()
    except Exception:
        thread_id = id(now)

    try:
        thread_name: str = threading.current_thread().name
    except Exception:
        thread_name = "unknown"

    try:
        iso_timestamp: str = datetime.datetime.fromtimestamp(
            now, tz=datetime.timezone.utc
        ).isoformat()
    except Exception:
        iso_timestamp = time.ctime(now)

    try:
        trace_id: str = uuid.uuid4().hex
    except Exception:
        trace_id = f"trace-{now}-{thread_id}"

    metadata: Dict[str, Any] = {
        "timestamp": now,
        "thread_id": thread_id,
        "version": _DEFAULT_VERSION,
        "iso_timestamp": iso_timestamp,
        "thread_name": thread_name,
        "trace_id": trace_id,
    }

    try:
        metadata["pid"] = os.getpid()
    except Exception:
        pass

    if extra_context:
        try:
            metadata.update(dict(extra_context))
