def execute_diagnostic_safely(
    check_name: str,
    check_func: Callable[..., Any],
    *args: Any,
    **kwargs: Any,
) -> DiagnosticResult:
    """Safely executes a diagnostic callable with telemetry tracking and exception isolation.

    Args:
