        **kwargs: Keyword arguments forwarded to check_func.

    Returns:
        DiagnosticResult: Verified result object reflecting execution outcome.
    """
    safe_check_name = str(check_name) if check_name is not None else "unnamed_check"

    if not validate_check_function(check_func):
        return DiagnosticResult.create(
            passed=False,
            message=f"Check '{safe_check_name}' failed: supplied function is not callable.",
            metadata={"check_name": safe_check_name, "error_type": "InvalidCallable"},
        )

    start_time = time.monotonic()
    try:
        result = check_func(*args, **kwargs)
