            message=f"Check '{safe_check_name}' encountered unhandled exception: {exc}",
            metadata={
                "check_name": safe_check_name,
                "duration_ms": duration_ms,
                "exception_type": type(exc).__name__,
                "exception_message": str(exc),
            },
        )

